const data = $('Webhook - Anfrage empfangen').item.json.body;
const binary = $('Webhook - Anfrage empfangen').item.binary || {};
const hasPdf = Boolean(binary.pdf);

const systemPrompt = 'Du bist ein professioneller Angebotsschreiber für eine Webentwicklungs-Agentur. Erstelle aus der Anfrage ein konkretes Angebot mit 3-5 Leistungspunkten, realistischem Zeitplan und Preisvorschlag. Ton: professionell, konkret, keine leeren Versprechungen. Preis: Im Rahmen des angegebenen Budgets, aber nicht am oberen Rand. Falls eine Projektbeschreibung als PDF-Dokument mitgeschickt wurde, nutze dessen Inhalt als Grundlage. Gib deine Antwort ausschließlich als valides JSON-Objekt zurück (kein Markdown, kein Fließtext drumherum) mit genau diesen Feldern: summary (2-3 Sätze Zusammenfassung der Anfrage), leistungen (Array aus 3-5 kurzen Leistungspunkten), zeitplan (Text mit dem realistischen Zeitplan), preisspanne (Text mit dem Preisvorschlag).';

const meta = {
  name: data.name,
  email: data.email,
  firma: data.firma || null,
  budget: data.budget,
  starttermin: data.starttermin || null,
  quelle: data.quelle || null,
};

let userContent;
if (hasPdf) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'pdf');
  const pdfBase64 = buffer.toString('base64');
  userContent = [
    { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: pdfBase64 } },
    { type: 'text', text: 'Kundendaten (Projektbeschreibung siehe angehaengtes PDF):\n' + JSON.stringify(meta) },
  ];
} else {
  userContent = JSON.stringify({ ...meta, projektbeschreibung: data.projektbeschreibung });
}

const claudeRequestBody = {
  model: 'claude-sonnet-5',
  max_tokens: 2000,
  system: systemPrompt,
  messages: [{ role: 'user', content: userContent }],
};

return { json: { claudeRequestBody, hasPdf } };

const data = $('Webhook - Anfrage empfangen').item.json.body;
const claudeContent = $input.item.json.content || [];
const claudeTextBlock = claudeContent.find((block) => block.type === 'text');
const claudeRaw = claudeTextBlock ? claudeTextBlock.text : '';
let ai;
let jsonText = claudeRaw.trim();
const fenceMatch = jsonText.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/);
if (fenceMatch) {
  jsonText = fenceMatch[1];
}
// Claude gibt gelegentlich echte Zeilenumbrueche innerhalb von String-Werten zurueck,
// was gegen die JSON-Spec verstoesst (Steuerzeichen muessten als \n escaped sein).
// Da JSON ausserhalb von Strings Whitespace ignoriert, ist ein Ersetzen durch Leerzeichen sicher.
jsonText = jsonText.replace(/[\r\n]+/g, ' ');
try {
  ai = JSON.parse(jsonText);
} catch (e) {
  ai = { summary: claudeRaw, leistungen: [], zeitplan: '', preisspanne: '' };
}

const now = new Date();
const datum = now.toLocaleDateString('de-DE');
const angebotsnummer = `AN-${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}-${Math.floor(1000 + Math.random() * 9000)}`;

const FIRMA_NAME = 'Deine Firma GmbH';
const FIRMA_KONTAKT = 'kontakt@deine-firma.de - +49 30 1234567';

const leistungenHtml = (ai.leistungen || []).map((punkt) => `<li>${punkt}</li>`).join('');

const html = `<!DOCTYPE html>
<html lang='de'>
<head><meta charset='utf-8'><title>Angebot ${angebotsnummer}</title></head>
<body style='font-family: Arial, sans-serif; color: #1e293b; max-width: 700px; margin: 0 auto;'>
  <header style='border-bottom: 2px solid #0f172a; padding-bottom: 16px; margin-bottom: 24px;'>
    <h1 style='margin: 0;'>${FIRMA_NAME}</h1>
    <p style='margin: 4px 0 0; color: #64748b;'>${FIRMA_KONTAKT}</p>
  </header>
  <p><strong>Datum:</strong> ${datum} &nbsp;|&nbsp; <strong>Angebotsnummer:</strong> ${angebotsnummer}</p>
  <p>Sehr geehrte/r ${data.name},</p>
  <p>${ai.summary || ''}</p>
  <h3>Leistungsbeschreibung</h3>
  <ul>${leistungenHtml}</ul>
  <h3>Zeitplan</h3>
  <p>${ai.zeitplan || ''}</p>
  <h3>Preis</h3>
  <p>${ai.preisspanne || ''}</p>
  <h3>Zahlungsbedingungen</h3>
  <p>50% Anzahlung, 50% bei Abnahme.</p>
  <p><strong>Gueltigkeitsdauer:</strong> Dieses Angebot ist 14 Tage gueltig.</p>
  <footer style='margin-top: 32px; border-top: 1px solid #e2e8f0; padding-top: 16px; color: #64748b; font-size: 0.85em;'>
    <p>${FIRMA_NAME} - ${FIRMA_KONTAKT}</p>
  </footer>
</body>
</html>`;

const indexHtmlBinary = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf-8'), 'index.html', 'text/html');

return {
  json: {
    name: data.name,
    email: data.email,
    firma: data.firma || '',
    budget: data.budget,
    projektbeschreibung: data.projektbeschreibung || '[Projektbeschreibung als PDF hochgeladen]',
    starttermin: data.starttermin || '',
    quelle: data.quelle || '',
    angebotsnummer,
    datum,
    summary: ai.summary || '',
    leistungen: (ai.leistungen || []).join('\n'),
    zeitplan: ai.zeitplan || '',
    preisspanne: ai.preisspanne || '',
    html,
  },
  binary: {
    index_html: indexHtmlBinary,
  },
};
